export const swordDamage = 2 * 4 + 5;
export const axeDamage = 5 * 4 + 5;
export const hammerDamage = 9 * 4 + 5;

function forge(metal) {
  return metal * 4 + 2;
}

export const swordDamage = forge(2);
export const axeDamage = forge(5);
export const hammerDamage = forge(9);

let hits = 0;

export function onHit() {
  hits = hits + 1;
  return hits;
}

export function healthAfterHit(health, damage) {
  if (health - damage < 0) {
    return 0;
  }
  return health - damage;
}
